def get_catalog():
    return CATALOG
def get_activities(lang="es",section="all"):
    chosen=[x for group in ACTIVITIES.values() for x in group] if section=="all" else ACTIVITIES.get(section,[])
    return [{"id":x["id"],"kind":x["kind"],"minutes":x["minutes"],"title":x.get(lang,x["es"])["title"],"description":x.get(lang,x["es"])["description"],"steps":x.get(lang,x["es"])["steps"]} for x in chosen]
def get_session(lang="es",kind="pause",minutes=3):
    minutes=max(3,min(10,int(minutes)))
    source=SESSIONS.get(kind,SESSIONS["pause"]).get(lang,SESSIONS["pause"]["es"])
    return {"title":source["title"],"kind":kind,"minutes":minutes,"steps":source["steps"],"language":lang}
def get_plant(plant_id,lang="es"):
    p=PLANTS.get(plant_id)
    return {"id":plant_id,**p.get(lang,p["es"])} if p else None
def get_program_day(lang="es",day=1):
    day=max(1,min(7,int(day)))
    kind,es,en=PROGRAM[day]
    return {"day":day,"title":es if lang=="es" else en,"kind":kind,"minutes":5 if day in (2,4,5,7) else 3,"completed_message":"Día completado. Continúa cuando quieras." if lang=="es" else "Day completed. Continue whenever you like."}
